import { NgTemplateOutlet } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, contentChild, inject, input, Signal, signal, TemplateRef, viewChild } from '@angular/core';
import { MODULE_NAME } from 'espd-common/config';
import { MessageConfig, MessageModule, MessageService } from 'espd-common/i18n';
import { ComparisonComponent } from '../comparison/comparison.component';

@Component({
	selector: 'espd-comparison-row',
	templateUrl: 'comparison-row.component.html',
	styleUrl: 'comparison-row.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [MessageModule, NgTemplateOutlet],
	host: {
		class: 'row',
		'[class.m-0]': '!!prevObj()'
	}
})
export class ComparisonRowComponent {
	public messageService = inject(MessageService);
	private comparisonComponent = inject(ComparisonComponent);

	public label = input<MessageConfig | string>();
	public fieldName = input<string>();

	public template = contentChild<TemplateRef<any>>(TemplateRef<any>);
	public defaultTemplate = viewChild<TemplateRef<any>>('defaultTemplate');

	private messagesAvailable = signal(false);
	private prevObj = computed(() => this.comparisonComponent.previous());
	private currentObj = computed(() => this.comparisonComponent.current());
	public oldValue = computed(() => this.fieldName() ? this.prevObj()?.[this.fieldName()!] : null);
	public currentValue = computed(() => this.fieldName() ? this.currentObj()?.[this.fieldName()!] : null);
	public isChanged = computed(() => this.prevObj() && JSON.stringify(this.oldValue()) !== JSON.stringify(this.currentValue()));
	public show = computed(() => !this.comparisonComponent.hideUnchanged() || this.isChanged());
	public valueTemplate = computed(() => this.template() || this.defaultTemplate()!);

	constructor() {
		this.messageService.waitFor(MODULE_NAME).subscribe(() => this.messagesAvailable.set(true));
	}

	public valueOrDash = (value: any): Signal<string> => computed(() => {
		return (typeof value === 'boolean' || !!value)
			? value.toString()
			: (this.messagesAvailable()
				? this.messageService.get('common.field.empty')
				: '');
	});
}